    p1, p2 = rng.sample(primes, 2)
    # Choose a 2-power factor to ensure multiple residue classes for x^2 ≡ b (mod m)
    two_exp = rng.choice([0,2,3])  # 1, 4, or 8 factor
    m = p1 * p2 * (2 ** two_exp)
    # Choose b to be a small perfect square so x^2 ≡ b has easy solutions across prime powers
    d = rng.choice([1,2])
    b = d * d
    # Choose q coprime to m, prime, not equal to p1/p2, and not 2
    q_candidates = [p for p in primes + [37,41,43] if p not in {p1, p2} and p % 2 == 1 and (m % p) != 0]
    if not q_candidates:
        continue
    q = rng.choice(q_candidates)
    # Choose modulus as product of 2^u and 5^v with u,v >= 3 to force CRT-like thinking
    u = rng.randint(3, 6)
    v = rng.randint(3, 6)
    modulus = (2 ** u) * (5 ** v)
    # Choose n large enough to force counting, but not so large that verification becomes unwieldy
    n = rng.randint(1200, 9000)
    # Quick feasibility checks: ensure gcd(m,q)=1
    import math
    if math.gcd(m, q) != 1:
        continue
