    L = m * q  # since gcd(m,q)=1
    # Compute inverse of m modulo q
    def egcd(a, b):
        if b == 0:
            return (a, 1, 0)
        g, x, y = egcd(b, a % b)
        return (g, y, x - (a // b) * y)
    def inv_mod(a, mod):
        a %= mod
        g, x, y = egcd(a, mod)
        if g != 1:
            return None
        return x % mod
    inv_m = inv_mod(m, q)
    if inv_m is None:
        continue
    S = set()
    for r in R:
        for s in range(1, q):  # exclude 0 to enforce q ∤ x
            # Solve r + m*t ≡ s (mod q) -> t ≡ inv_m * (s - r) (mod q)
            t = (inv_m * ((s - r) % q)) % q
            x_res = (r + m * t) % L
            S.add(x_res)
    # Difficulty enforcement: ensure many residue classes per block
    if len(S) < 6:
        continue
    # Approximate size of K so it's not astronomically large
    avg_gap = L / max(1, len(S))
